export interface ChapadaMetadata {
  title: string;
  basemap_level1: string;
  basemap_level2?: string;
  basemap_level3?: string;
  source: string;
  layer_source: string;
  source_gpkg: string;
  periodo_narrativo: string;
  views_used_for_geometry?: string[];
  tabular_view?: string;
  alert_layer_parts?: string[];
  rules: {
    area_rule: string;
    vpresso_field: string;
    car_field: string;
  };
}

export interface MunicipioRankingItem {
  municipio: string;
  total_area_ha: number;
  area_total_municipio_ha: number;
  total_alertas: number;
  alertas_na_apa: number;
  proporcao_apa_pct: number | null;
  rank: number;
}

export interface MunicipioAnnualStat {
  ano: number;
  area_ha: number;
  alertas: number;
}

export interface MunicipioSeries {
  municipio: string;
  years: MunicipioAnnualStat[];
  area_total_ha?: number;
  total_alertas?: number;
}

export interface AlertProperties {
  fid: number;
  alerta_fid?: number;
  CODEALERTA: number;
  CD_MUN: string;
  MUNICIPIO: string;
  AREAHA: number;
  ANODETEC: number;
  FONTE: string;
  ESTADO: string;
  DATADETEC: string;
  DTIMGANT?: string;
  DTIMGDEP?: string;
  DTPUBLI?: string;
  SIGLA_UF?: string;
  uc_id?: string;
  AREA_NA_APA_HA?: number;
  INSIDE_APA?: boolean;
  CLASSE_APA?: string;
  AREA_FORA_APA_HA?: number;
  VPRESSAO?: string;
  CAR?: string;
}

